with scope as materialized (
 select cp.*,b.name brand from public.catalog_products cp join public.brands b on b.id=cp.brand_id and b.organization_id=cp.organization_id
 where cp.organization_id='1e4c5e99-e387-41aa-a6d3-cbe74558f766' and cp.brand_id='821a7c95-dd21-4ae8-b55b-fe463fa0b7ca'
), values_for_export as (
 select array[btrim(coalesce(product_code,'')),btrim(brand),coalesce(ean,''),coalesce(description,''),coalesce(description_tr,''),coalesce(oem_no,''),coalesce(vehicle,''),coalesce(vehicle_model,''),coalesce(hs_code,''),coalesce(origin,''),coalesce(market_segment,''),coalesce(trim_scale(weight_kg)::text,''),coalesce(image_url,''),coalesce(nullif(lifecycle_status,''),'active'),coalesce(lifecycle_note,'')] as fields from scope
), hashes as (
 select md5((select string_agg(octet_length(escaped)::text||':'||escaped,'' order by ord) from (select ord,case when ord<>12 and val ~ '^[[:space:]]*[=+@-]' then chr(39)||val else val end escaped from unnest(fields) with ordinality as f(val,ord)) e)) row_hash,md5(fields[1]) key_hash from values_for_export
)
select clock_timestamp() observed_at,(select count(*) from scope) catalog_rows,(select count(distinct btrim(product_code)) from scope) distinct_product_codes,(select count(*) from scope where market_segment is not null) nonnull_market_segments,md5(string_agg(row_hash,'' order by row_hash collate "C")) semantic_multiset_md5,md5(string_agg(key_hash,'' order by key_hash collate "C")) product_code_multiset_md5,public.get_catalog_export_version('1e4c5e99-e387-41aa-a6d3-cbe74558f766','821a7c95-dd21-4ae8-b55b-fe463fa0b7ca','') current_data_version from hashes;

