with page as materialized(select ordinal,source_key,payload from export_snapshot_private.rows where snapshot_id='60fc0af5-82c2-46a4-971e-0e84f3a0e55b' and ordinal between 1 and 100000), checked as (
select p.*,md5((select string_agg(octet_length(v)::text||':'||v,'' order by ord) from unnest(array[coalesce(payload->>'code',''),coalesce(payload->>'description',''),trim_scale((payload->>'price')::numeric)::text,coalesce(payload->>'priceDate',''),case when payload->>'discontinued'='true' then 'Discontinued'||case when coalesce(payload->>'replacementCode','')<>'' then '; replacement: '||(payload->>'replacementCode') else '' end else 'Active' end]) with ordinality f(v,ord))) row_hash,
(select min(r.buy_price) from public.supplier_price_release_rows r where r.release_id='e9517ad0-3e11-4f52-a73f-71875a5b2d4a' and r.normalized_code=p.source_key and r.row_status='accepted' and r.buy_price>0 and r.currency='EUR' and r.valid_from<=current_date) buy_price
from page p)
select count(*) row_count,md5(string_agg(row_hash,'' order by ordinal)) chunk_md5,count(*) filter(where payload->>'brand' is distinct from 'Clevite' or payload->>'currency' is distinct from 'EUR') scope_mismatches,count(*) filter(where buy_price is null) missing_prices,count(*) filter(where (payload->>'price')::numeric is distinct from round(buy_price*1.10,2)) price_mismatches from checked;
